import{_ as t,c as r,o as s,ah as e}from"./chunks/framework.Ch_PcVtW.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART3/3/0_context_summary.md","filePath":"scripts/output/PART3/3/0_context_summary.md"}'),l={name:"scripts/output/PART3/3/0_context_summary.md"};function n(i,o,a,g,c,_){return s(),r("div",null,[...o[0]||(o[0]=[e('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1) 本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1) 本篇主题与主要内容概述&quot;">​</a></h2><p>本篇围绕Novel Core于2024年1月17日登上日本武道馆举行个人公演展开，回顾他从BMSG创立初期立下梦想，到三年后实现目标的历程。SKY-HI谈及两人之间的信任、支持与相互成就，强调艺人的舞台必须源于本人意志，不能被“大人的盘算”左右。同时，他进一步阐释了BMSG培养个人艺人的意义，并展望Novel Core未来进军巨蛋，以及BMSG旗下多位solo艺人共同创作、走向全球的可能性。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2) 人物/术语/语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2) 人物/术语/语气风险点&quot;">​</a></h2><ul><li><strong>人物关系</strong>：SKY-HI是BMSG社长、制作人及solo艺人；Novel Core是BMSG首位签约艺人，统一使用“SKY-HI”“Novel Core”，不要混译或擅自改写。</li><li><strong>称呼处理</strong>：原文中的「コア」是SKY-HI对Novel Core的亲昵称呼，可译为“Core”或“科亚”；建议首次注明“Novel Core（下文简称Core）”，保持全文一致。</li><li><strong>日本武道馆</strong>：译为“日本武道馆”，不要简化为“武道馆”，标题和正文需统一。</li><li><strong>BMSG核心理念</strong>：「才能を殺さない」宜译为“不要扼杀才华”，避免译成过于生硬的“杀死才能”。</li><li><strong>“大人の思惑”</strong>：不是单纯的“成年人想法”，应结合语境译为“大人的盘算／成人世界的意图”，突出对商业操控痕迹的警惕。</li><li><strong>“立たされたステージ”</strong>：强调“被安排、被推上去的舞台”，不可译成普通的“站上的舞台”。</li><li><strong>“アーティスト実務”</strong>：指作曲、演出、歌单等具体创作与舞台决策，可译为“艺人创作与执行事务”。</li><li><strong>行业术语</strong>：<code>レーベル</code>为“厂牌”；<code>プロダクション</code>为“经纪公司／制作公司”；<code>ソロアーティスト</code>为“solo艺人／个人艺人”；<code>ボーイバンド</code>为“男团”；<code>アートフォーム</code>可保留英文并注释为“艺术形式”。</li><li><strong>语气基调</strong>：SKY-HI兼具管理者的理性和艺术家的热情，既要保留论述的严谨，也要呈现亲切、坦率、偶尔幽默的口语感。</li><li><strong>情感表达</strong>：「尊い」「筆舌に尽くしがたい」「ヘロヘロ」需避免过度书面化，分别传达“珍贵／难以用言语形容／累得筋疲力尽”等情绪。</li><li><strong>敏感表达</strong>：「あともう1回は内緒です(笑)」应保留轻松、保密的玩笑感，不宜正式化。</li><li><strong>原文疑似排版或录入问题</strong>：如「かなわな「いかもしれない」「やってみよ「う」」等引号错位，翻译时应按上下文修正，不保留异常符号。</li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3) 翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3) 翻译时建议重点&quot;">​</a></h2><ul><li><strong>标题要兼顾事实与象征意义</strong>：突出Novel Core武道馆公演不仅是个人梦想的实现，也是BMSG创立初期目标的兑现。</li><li><strong>准确处理“梦想”叙事</strong>：全文核心不是励志口号，而是“相信梦想—拆解差距—持续行动—共同实现”的管理与制作方法论。</li><li><strong>保留第一人称访谈感</strong>：避免翻译成企业宣传稿，要让读者感到这是SKY-HI在回顾具体经历、分享真实感受。</li><li><strong>区分“支持”与“干预”</strong>：SKY-HI提供建议和反馈，但不替艺人决定作品、演出或歌单，这是本篇的重要价值判断。</li><li><strong>处理长句时适度拆分</strong>：日文原文信息密度较高，可拆成中文短句，但不要削弱因果关系和层层推进的逻辑。</li><li><strong>保留音乐行业语境</strong>：如“武道馆”“巨蛋”“solo艺人”“全球热门”等词，建议采用业内通行译法，必要时保留英文并加中文注释。</li><li><strong>结尾应保留开放感</strong>：关于多位solo艺人合作的设想尚未正式公布，译文应体现“期待与可能性”，不要写成已确定的企划。</li></ul>',6)])])}const m=t(l,[["render",n]]);export{u as __pageData,m as default};
